import numpy as np
from scipy import stats

MAX_DRIVERS = 5

def design(feats):
    # Calculate effect sizes for all features
    effect_sizes = []
    p_values = []

    for i, fid in enumerate(feats.ids):
        if feats.types[i] == 'clinical' or feats.types[i] == 'cohort':
            # For clinical/cohort variables, check correlation with outcome
            corr = np.corrcoef(feats.x[:, i], feats.y)[0, 1]
            effect_sizes.append(abs(corr))
        else:
            # For other features, use Welch's t-test
            group0 = feats.x[feats.y == 0, i]
            group1 = feats.x[feats.y == 1, i]
            if len(group0) > 1 and len(group1) > 1:
                t_stat, p_val = stats.ttest_ind(group0, group1, equal_var=False)
                effect_sizes.append(abs(t_stat))
                p_values.append(p_val)
            else:
                effect_sizes.append(0)

    # Find top features by effect size
    sorted_indices = np.argsort(effect_sizes)[::-1]

    # Select top features, avoiding near-duplicates
    keep_features = []
    used_pairs = set()

    for idx in sorted_indices:
        if len(keep_features) >= MAX_DRIVERS:
            break

        fid = feats.ids[idx]

        # Check if this feature is highly correlated with any already selected feature
        is_duplicate = False
        for kept_fid in keep_features:
            col_a = feats.column(kept_fid)
            col_b = feats.column(fid)
            if abs(np.corrcoef(feats.x[:, col_a], feats.x[:, col_b])[0, 1]) >= 0.6:
                is_duplicate = True
                break

        if not is_duplicate:
            keep_features.append(fid)

    # If no strong associations found, return empty design
    if len(keep_features) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Build regression features
    columns = tuple(keep_features)

    # Identify drivers (non-clinical features)
    drivers = tuple([fid for fid in columns if feats.types[feats.column(fid)] != 'clinical' and feats.types[feats.column(fid)] != 'cohort'])

    # Limit drivers to max 4 as required
    if len(drivers) > 4:
        drivers = drivers[:4]

    # Simple product terms between top features
    products = []
    top_fids = list(columns)[:3]  # Top 3 features
    for i in range(len(top_fids)):
        for j in range(i+1, len(top_fids)):
            products.append((top_fids[i], top_fids[j]))

    # Weighted score using top features
    loadings = {}
    for i, fid in enumerate(columns):
        if i < 5:  # Only include top 5 in loadings
            loadings[fid] = 1.0 / (i + 1)  # Decreasing weights

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)

